function initTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(o=>{o.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>e.classList.remove("active")),o.classList.add("active"),o.setAttribute("aria-selected","true"),document.getElementById(o.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const e=document.getElementById("chaul-quiz-form"),t=document.getElementById("quiz-result"),o={q1:"2",q2:"2"};e&&e.addEventListener("submit",n=>{n.preventDefault();let i=0;const l=new FormData(e);for(let[e,t]of l.entries())o[e]===t&&i++;const r=Object.keys(o).length;t.textContent=i===r?`🎉 Perfect! ${i}/${r}`:`You scored ${i}/${r}`,t.style.color=i===r?"green":"orange"})}function initGalleryModal(){const e=document.getElementById("gallery-modal"),t=document.getElementById("modal-title"),o=document.getElementById("modal-desc"),n=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(n=>{n.addEventListener("click",()=>{t.textContent=n.getAttribute("data-title"),o.textContent=n.getAttribute("data-desc"),e.classList.add("active")})}),n&&n.addEventListener("click",()=>e.classList.remove("active")),window.addEventListener("click",t=>{t.target===e&&e.classList.remove("active")})}function initScrollTop(){const e=document.getElementById("btn-scroll-top");e&&(window.addEventListener("scroll",()=>e.classList.toggle("visible",window.scrollY>300)),e.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("chaul-port-explorer/index.html",[{id:"chaul-overview",title:"Chaul Historical Background",description:"History of the Konkan port.",link:"chaul-port-explorer/index.html#overview"},{id:"chaul-fort",title:"Revdanda Fort",description:"The Portuguese coastal stronghold.",link:"chaul-port-explorer/index.html#monuments"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});